export const records = [{"schema_version":1,"id":"AUT-0586","slug":"new-buyer-ad-conversion-classification-check","title":"Звірка ознаки нового покупця в рекламній конверсії","summary":"Для придатної покупки перевіряють історію покупця та передану ознаку new/returning; невідомого покупця не називають новим за відсутністю даних.","problem":"Гостьову покупку передали як нову, хоча історія клієнта невідома. Різні джерела використовують різні строки, а звіт залучення нових покупців завищує результат.","outcome":"Придатна конверсія покупки має пояснену ознаку за погодженим періодом і перевірений параметр передачі; unknown та інші типи конверсій не приховані.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","owner"],"industries":["cross-industry"],"triggers":["Налаштовують або змінюють ознаку нового покупця для рекламної конверсії покупки."],"workflow_steps":["Погодити визначення нового покупця, період історії й джерело ідентифікації; нового контакту CRM не прирівнювати до першої покупки.","Звірити контрольні покупки нового, повторного й невідомого покупця; неповну історію або гостьовий checkout залишити невизначеними.","Зіставити фактичний маршрут конверсії з потрібним типом параметра; new_customer та customer_type не передавати як взаємозамінні поля без контракту.","Перевірити передане значення в контрольному сценарії та погодити редакцію; тестова доставка поля не підтверджує правильність історії.","Після потрібного періоду зіставити звіти new/returning/unknown із охопленням; допоміжні непокупкові конверсії й дані до активації не оголошувати новими покупцями."],"requirements":["Є погоджене визначення нового покупця та придатна історія покупок.","Є конверсія категорії Purchase і контрольний маршрут читання переданого параметра."],"limitations":["Рекламна система має власне визначення й технічні межі; режим лише нових покупців не гарантує повного виключення повторних.","Невідомий покупець не дорівнює новому; час створення контакту не замінює історію покупок.","Підтримка параметра залежить від маршруту; старі приклади API не застосовують без актуальної перевірки.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Гостьову покупку передали як нову, хоча історія клієнта невідома. Різні джерела використовують різні строки, а звіт залучення нових покупців завищує результат."],"synonyms":["new_customer конверсія","new returning unknown покупець","перевірка customer_type реклами"],"search_queries":["як перевірити ознаку нового покупця в рекламній конверсії без завищення гостьових покупок"],"sources":[{"type":"vendor_documentation","url":"https://support.google.com/google-ads/answer/12077475","title":"Google Ads: New customer acquisition parameter","checked_at":"2026-10-10","supports":"Прочитано Purchase, різні типи new_customer/customer_type, невизначеність guest checkout й перевірку параметра. Строк визначення погоджується, а не копіюється як обов’язкова константа. Підтримка різних маршрутів потребує актуального контракту."},{"type":"vendor_documentation","url":"https://support.google.com/google-ads/answer/14005157?hl=en","title":"Google Ads: Troubleshooting new customer acquisition","checked_at":"2026-10-10","supports":"Описано джерела визначення покупця, обмеження навіть New Customer Only, match rate та new/returning/unknown/additional у звітах. Класифікація Purchase відрізняється від допоміжних конверсій і даних до активації."},{"type":"inferred_pattern","title":"Редакційна модель допусків і рекламних рішень","supports":"Погодження, контроль редакцій, винятки, приклад, питання й години — гіпотези для аудиту. Джерела описують власні продукти; готову реалізацію PlanFix чи клієнтський результат CRMCUSTOMS не підтверджено."}],"status":"draft","variants":[{"id":"new-buyer-ad-conversion-classification-check-tracked","title":"Контроль із підтвердженням результату","description":"Для придатної покупки перевіряють історію покупця та передану ознаку new/returning; невідомого покупця не називають новим за відсутністю даних.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Контрольний гостьовий checkout не мав достатньої історії. Команда прибрала безумовне true й зберегла невизначеність; відому повторну покупку перевірили окремо.","implementation_methods":["Погодити визначення нового покупця та контрольні приклади з історією.","Звіряти обчислену ознаку, фактичний параметр і придатний рекламний звіт."],"complexity":"medium","hours_min":22,"hours_max":44,"requirements":["Є погоджене визначення нового покупця та придатна історія покупок.","Є конверсія категорії Purchase і контрольний маршрут читання переданого параметра."],"limitations":["Рекламна система має власне визначення й технічні межі; режим лише нових покупців не гарантує повного виключення повторних.","Невідомий покупець не дорівнює новому; час створення контакту не замінює історію покупок.","Підтримка параметра залежить від маршруту; старі приклади API не застосовують без актуальної перевірки."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0557","reason":"Вибір цілей оптимізації не підтверджує ознаки нового покупця конкретної покупки."},{"type":"related","target_id":"AUT-0543","reason":"Ідентифікатор покупки захищає від повторного обліку, але не визначає історію покупця."},{"type":"related","target_id":"AUT-0561","reason":"Право на реферальну винагороду має власні умови; рекламна ознака не є рішенням видачі."}],"configurator_questions":[{"id":"new-buyer-ad-conversion-classification-check-identity","question":"Чи покупки одного клієнта надходять із кількох торгових систем?","help_text":"Погодьте повноту історії та стабільне зіставлення без примусового вгадування гостьових покупців.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте повноту історії та стабільне зіставлення без примусового вгадування гостьових покупців."}]},{"id":"new-buyer-ad-conversion-classification-check-routes","question":"Чи потрібно перевіряти кілька маршрутів передачі конверсій?","help_text":"Для кожного маршруту звірте тип параметра й підтримку; не копіюйте застарілий API-приклад.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Для кожного маршруту звірте тип параметра й підтримку; не копіюйте застарілий API-приклад."}]}]},{"schema_version":1,"id":"AUT-0587","slug":"ad-platform-auto-recommendation-permission-review","title":"Перегляд дозволу на автоматичні рекомендації реклами","summary":"Команда звіряє, які типи рекомендацій рекламної платформи можуть самостійно змінювати акаунт, хто їх увімкнув і чи відповідають вони погодженій політиці.","problem":"Власник погодив один тип оптимізації, але в акаунті ввімкнено весь набір. Команда не знає, хто надав дозвіл, і плутає вимкнення майбутніх рекомендацій зі скасуванням минулих змін.","outcome":"Автоматична оптимізація платформи має погоджений перелік дозволених типів і перевірені налаштування; минулі зміни та майбутній дозвіл контролюють окремо.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","owner"],"industries":["cross-industry"],"triggers":["Змінився дозвіл на автоматичні рекомендації або настав строк перегляду цієї політики акаунта."],"workflow_steps":["Зберегти погоджені типи автоматичних рекомендацій та їхні межі на рівні акаунта; не підміняти політику власним правилом зміни ставки.","Прочитати фактичні ввімкнені типи, дату й автора opt-in із доступної історії; неповну історію лишити невідомою.","Зіставити ввімкнені набори з дозволом і поточним змістом типів; новий або змінений тип передати на рішення власнику реклами.","За погодженням змінити підписку на конкретні типи й перечитати налаштування; вимкнення не оголошувати відкатом уже застосованих змін.","Окремо зіставити чергу й історію застосованих рекомендацій з політикою; минулі відхилення передати на обґрунтоване виправлення з урахуванням наступних змін."],"requirements":["Є погоджена політика автоматичних рекомендацій та власник рішення.","Є доступ до налаштувань opt-in, черги й історії змін акаунта."],"limitations":["Типи рекомендацій змінюються; набір треба перевіряти в поточній системі, а не фіксувати назавжди.","Вимкнення майбутніх рекомендацій не скасовує минулі зміни та не гарантує автоматичного відкату.","Google описує автооптимізацію на рівні акаунта без автоматичного збільшення бюджету; це не універсальне правило інших систем.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Власник погодив один тип оптимізації, але в акаунті ввімкнено весь набір. Команда не знає, хто надав дозвіл, і плутає вимкнення майбутніх рекомендацій зі скасуванням минулих змін."],"synonyms":["auto apply opt-in review","політика автоматичної оптимізації реклами","дозвіл рекомендацій Google Ads"],"search_queries":["як перевірити хто ввімкнув автоматичні рекомендації реклами і які типи змін дозволені"],"sources":[{"type":"vendor_documentation","url":"https://support.google.com/google-ads/answer/10276359?hl=en","title":"Google Ads: Manage auto-apply recommendations","checked_at":"2026-10-10","supports":"Описано вибір типів або наборів, налаштування акаунта, історію ввімкнення й автора, статистику застосувань та вимкнення конкретного типу. Редакційна політика й рішення власника — проєктна модель."},{"type":"vendor_documentation","url":"https://support.google.com/google-ads/answer/10279006","title":"Google Ads: Applying recommendations automatically","checked_at":"2026-10-10","supports":"Описано рівень акаунта, чергу, можливість відхилення, зміну доступних типів та відсутність автоматичного підвищення бюджету. Це інший механізм, ніж власні scheduled rules; рекомендація не гарантує бізнесового ефекту."},{"type":"inferred_pattern","title":"Редакційна модель допусків і рекламних рішень","supports":"Погодження, контроль редакцій, винятки, приклад, питання й години — гіпотези для аудиту. Джерела описують власні продукти; готову реалізацію PlanFix чи клієнтський результат CRMCUSTOMS не підтверджено."}],"status":"draft","variants":[{"id":"ad-platform-auto-recommendation-permission-review-tracked","title":"Контроль із підтвердженням результату","description":"Команда звіряє, які типи рекомендацій рекламної платформи можуть самостійно змінювати акаунт, хто їх увімкнув і чи відповідають вони погодженій політиці.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Історія показала ввімкнення цілого набору замість одного погодженого типу. Власник змінив майбутній дозвіл, а вже застосовану зміну окремо передав на перевірку.","implementation_methods":["Вести політику дозволених типів рекомендацій із рішенням власника.","Звіряти opt-in, чергу та історію без сліпого повернення старих значень."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Є погоджена політика автоматичних рекомендацій та власник рішення.","Є доступ до налаштувань opt-in, черги й історії змін акаунта."],"limitations":["Типи рекомендацій змінюються; набір треба перевіряти в поточній системі, а не фіксувати назавжди.","Вимкнення майбутніх рекомендацій не скасовує минулі зміни та не гарантує автоматичного відкату.","Google описує автооптимізацію на рівні акаунта без автоматичного збільшення бюджету; це не універсальне правило інших систем."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0554","reason":"Власне правило має задані командою умови й частоту; тут переглядають делегований платформі дозвіл на типи рекомендацій."},{"type":"related","target_id":"AUT-0518","reason":"Темп бюджету є окремим спостереженням; opt-in не означає дозвіл підвищувати бюджет."}],"configurator_questions":[{"id":"ad-platform-auto-recommendation-permission-review-accounts","question":"Чи потрібно переглядати кілька рекламних акаунтів?","help_text":"Зберігайте окремі політики, власників та історію без автоматичного поширення одного дозволу.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Зберігайте окремі політики, власників та історію без автоматичного поширення одного дозволу."}]},{"id":"ad-platform-auto-recommendation-permission-review-history","question":"Чи потрібно зіставляти рекомендації з історією наступних ручних змін?","help_text":"Погодьте межі читання й виправлення; старе значення не перезаписує пізнішу дозволену зміну.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Погодьте межі читання й виправлення; старе значення не перезаписує пізнішу дозволену зміну."}]}]},{"schema_version":1,"id":"AUT-0588","slug":"deal-product-request-response-approval","title":"Погодження продуктового запиту для активної угоди","summary":"Запит покупця на відсутню можливість пов’язують з угодою й продуктовою ідеєю; продавець отримує погоджену відповідь замість самостійної обіцянки релізу.","problem":"Покупець чекає потрібної можливості, але продавець записав її лише в листуванні й пообіцяв непогоджений строк. Продуктова команда не бачить пов’язаних угод, а зміна статусу ідеї не доходить до менеджера.","outcome":"Угода має пов’язаний продуктовий запит, пояснене рішення команди та погоджену відповідь покупцю; статус ідеї не перетворюється на непогоджену обіцянку.","category":"sales-crm","subcategory":"sales-operations","roles":["sales-manager","sales-representative"],"industries":["cross-industry"],"triggers":["Покупець назвав відсутню можливість умовою продовження активної угоди."],"workflow_steps":["Зберегти угоду, потрібний сценарій покупця, критичність і бажаний строк; бажання покупця не записувати як обіцянку компанії.","Знайти наявну продуктову ідею або створити нову; пов’язати окремий контекст угоди без створення копії ідеї для кожного продавця.","Передати продуктовому власнику сценарій і вплив на рішення; суми пов’язаних угод не називати гарантованим доходом.","Погодити відповідь: наявний обхідний сценарій, розгляд, відмова або дозволене зобов’язання; строк повідомляти лише з відповідним рішенням.","Після зміни статусу ідеї повідомити власників пов’язаних угод і звірити надану покупцю відповідь; завершення розгляду не прирівнювати до готовності функції."],"requirements":["Є активна угода, продуктовий власник та правила комерційних обіцянок.","Є реєстр ідей зі стабільними ключами й доступний маршрут повернення статусу продавцю."],"limitations":["Це не розробка функції, управління всім roadmap або передпродажний пілот.","Джерело описує інтеграцію Aha! Ideas Advanced із Salesforce REST; інші системи потребують перевіреного адаптера.","Статус, голос клієнта та сума opportunity не гарантують реалізації, дати релізу або виграшу угоди.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Покупець чекає потрібної можливості, але продавець записав її лише в листуванні й пообіцяв непогоджений строк. Продуктова команда не бачить пов’язаних угод, а зміна статусу ідеї не доходить до менеджера."],"synonyms":["покупець чекає нову функцію","продуктова ідея блокує угоду","запит можливості з CRM"],"search_queries":["як передати продуктовий запит покупця з угоди і погодити відповідь без обіцянки релізу"],"sources":[{"type":"vendor_documentation","url":"https://support.aha.io/aha-ideas/integrations/salesforce/use-salesforce-gather-customer-feedback~7444675480031526686","title":"Aha! Ideas: Gather customer feedback with Salesforce","checked_at":"2026-10-10","supports":"Описано пошук або створення ідеї з opportunity/account/case, proxy vote з контекстом, зв’язок організації та повернення статусу. Вартість передається з opportunity. Маршрут дозволу відповіді й обіцянки — наша проєктна модель, не заявлена готова функція."},{"type":"inferred_pattern","title":"Редакційна модель комерційних запитів і рекламних меж","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують власні продукти або рекомендації; готову реалізацію PlanFix чи клієнтський результат CRMCUSTOMS не підтверджено."}],"status":"draft","variants":[{"id":"deal-product-request-response-approval-tracked","title":"Контроль із підтвердженням результату","description":"Запит покупця на відсутню можливість пов’язують з угодою й продуктовою ідеєю; продавець отримує погоджену відповідь замість самостійної обіцянки релізу.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Покупець чекає імпорту потрібного формату. Продавець пов’язав угоду з наявною ідеєю; продуктовий власник дозволив повідомити про розгляд без дати, а менеджер зберіг цю відповідь у переговорах.","implementation_methods":["Вести зв’язки ідеї з угодами та окремий контекст кожного покупця.","Повертати перевірений статус і погоджену відповідь власникам активних угод."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Є активна угода, продуктовий власник та правила комерційних обіцянок.","Є реєстр ідей зі стабільними ключами й доступний маршрут повернення статусу продавцю."],"limitations":["Це не розробка функції, управління всім roadmap або передпродажний пілот.","Джерело описує інтеграцію Aha! Ideas Advanced із Salesforce REST; інші системи потребують перевіреного адаптера.","Статус, голос клієнта та сума opportunity не гарантують реалізації, дати релізу або виграшу угоди."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0577","reason":"Пілот перевіряє наявні сценарії; тут покупець запитує відсутню можливість і чекає продуктового рішення."},{"type":"related","target_id":"AUT-0515","reason":"Редакція пропозиції зберігає погоджені умови, а не опрацьовує продуктову ідею."},{"type":"related","target_id":"AUT-0549","reason":"Виведення продукту з продажів не вирішує запит на нову можливість."}],"configurator_questions":[{"id":"deal-product-request-response-approval-systems","question":"Чи продуктові ідеї й угоди зберігаються в різних системах?","help_text":"Перевірте ключі, доступ і повернення статусу без припущення готової інтеграції.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Перевірте ключі, доступ і повернення статусу без припущення готової інтеграції."}]},{"id":"deal-product-request-response-approval-promises","question":"Чи потрібен окремий дозвіл на комерційну обіцянку строку або обсягу?","help_text":"Зберігайте уповноважене рішення та точний дозволений текст відповіді.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Зберігайте уповноважене рішення та точний дозволений текст відповіді."}]}]},{"schema_version":1,"id":"AUT-0589","slug":"dynamic-ad-destination-boundary-check","title":"Контроль меж автоматичного вибору рекламної сторінки","summary":"Маркетолог перевіряє, які сторінки рекламна платформа може вибрати замість заданої цілі; погоджені винятки враховують режим розширення та товарні адреси.","problem":"Команда завантажила список сторінок і вважає його єдиними цілями реклами. Автоматичне розширення направляє на інші сторінки домену, а вимкнення не пояснює окремі товарні адреси.","outcome":"Кампанія має пояснені межі автоматичного вибору кінцевої сторінки та перевірені винятки; неперевірені маршрути не оголошують забороненими.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","owner"],"industries":["cross-industry"],"triggers":["Запускають кампанію з автоматичним вибором кінцевої сторінки або змінюють дозволені напрямки."],"workflow_steps":["Зафіксувати кампанію, режим розширення кінцевої адреси, дозволені сторінки й заборонені напрямки; окремо записати товарні групи та їхні адреси.","Зіставити режим із фактичними джерелами цілей; page feed при ввімкненому розширенні не вважати повним обмеженням домену.","Погодити виключення адрес або зміну режиму; врахувати товарні URL та доступні способи обмеження, а не обіцяти одну універсальну ціль.","Застосувати дозволену редакцію й прочитати режим, список виключень і зачеплені активи; видалення спільного автоматичного активу перевіряти на рівні всієї кампанії.","Зіставляти доступні спостереження кінцевих цілей із погодженими межами; неповну історію показів не вважати доказом відсутності іншого маршруту."],"requirements":["Є кампанія з автоматичним вибором цілі та погоджені дозволені напрямки.","Є доступ до режиму, виключень і доступних джерел рекламних URL."],"limitations":["Це не перенесення сторінок і не перевірка прив’язок додаткових sitelinks.","Google Performance Max має окремі правила Final URL expansion, page feeds і Merchant Center listing groups; їх не переносять на всі платформи.","Допустима ціль не гарантує показу; відсутність URL у неповному звіті не доводить заборони.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Команда завантажила список сторінок і вважає його єдиними цілями реклами. Автоматичне розширення направляє на інші сторінки домену, а вимкнення не пояснює окремі товарні адреси."],"synonyms":["Final URL expansion межі","реклама вибирає іншу сторінку","виключення рекламних посадкових URL"],"search_queries":["як обмежити автоматичний вибір сторінок реклами щоб page feed не направляв на інші адреси"],"sources":[{"type":"vendor_documentation","url":"https://support.google.com/google-ads/answer/14337539?hl=en","title":"Google Ads: Final URL expansion in Performance Max","checked_at":"2026-10-10","supports":"Описано автоматичний вибір інших сторінок домену, page feed та URL exclusions. При ввімкненому розширенні feed не обмежує всі цілі; вимкнення не прибирає товарні адреси Merchant Center listing groups. Видалення створеного активу впливає на кампанію. Погодження меж — проєктна модель."},{"type":"inferred_pattern","title":"Редакційна модель комерційних запитів і рекламних меж","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують власні продукти або рекомендації; готову реалізацію PlanFix чи клієнтський результат CRMCUSTOMS не підтверджено."}],"status":"draft","variants":[{"id":"dynamic-ad-destination-boundary-check-tracked","title":"Контроль із підтвердженням результату","description":"Маркетолог перевіряє, які сторінки рекламна платформа може вибрати замість заданої цілі; погоджені винятки враховують режим розширення та товарні адреси.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Для кампанії погодили лише сторінки послуги. Маркетолог виявив увімкнене розширення й виключив непотрібні розділи; товарні цілі перевірив окремо, не назвавши feed універсальним обмеженням.","implementation_methods":["Вести редакцію дозволених і заборонених рекламних напрямків із фактичним режимом вибору.","Звіряти збережені налаштування та доступні спостереження кінцевих цілей."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Є кампанія з автоматичним вибором цілі та погоджені дозволені напрямки.","Є доступ до режиму, виключень і доступних джерел рекламних URL."],"limitations":["Це не перенесення сторінок і не перевірка прив’язок додаткових sitelinks.","Google Performance Max має окремі правила Final URL expansion, page feeds і Merchant Center listing groups; їх не переносять на всі платформи.","Допустима ціль не гарантує показу; відсутність URL у неповному звіті не доводить заборони."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0581","reason":"Sitelinks мають явні прив’язки; тут платформа автоматично вибирає основну кінцеву сторінку."},{"type":"related","target_id":"AUT-0208","reason":"Міграція URL перевіряє стару й нову адресу, а не дозволену область рекламного вибору."},{"type":"related","target_id":"AUT-0554","reason":"Виконання власного рекламного правила не підтверджує межі динамічного вибору сторінок."}],"configurator_questions":[{"id":"dynamic-ad-destination-boundary-check-products","question":"Чи кампанія також використовує товарні групи й адреси Merchant Center?","help_text":"Зіставте окремі товарні маршрути з режимом розширення; не обіцяйте одну ціль після вимкнення.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Зіставте окремі товарні маршрути з режимом розширення; не обіцяйте одну ціль після вимкнення."}]},{"id":"dynamic-ad-destination-boundary-check-accounts","question":"Чи межі потрібно підтримувати в кількох кампаніях або акаунтах?","help_text":"Зберігайте окремі режими й винятки без неконтрольованого поширення зміни.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Зберігайте окремі режими й винятки без неконтрольованого поширення зміни."}]}]},{"schema_version":1,"id":"AUT-0590","slug":"customer-reference-call-consent-match","title":"Погодження референсної розмови клієнта з покупцем","summary":"Для покупця добирають клієнта з доречним досвідом, погоджують конкретну участь і зберігають факт розмови, щоб не перевантажувати одних клієнтів запитами.","problem":"Продавець передає контакт клієнта покупцю без згоди. Досвід клієнта не відповідає запиту, а кілька менеджерів одночасно просять його про нові розмови.","outcome":"Запит покупця має придатного клієнта, погоджену участь і зафіксований результат розмови або пояснену відмову; чужий контакт не передають без дозволу.","category":"sales-crm","subcategory":"sales-operations","roles":["sales-manager","sales-representative"],"industries":["cross-industry"],"triggers":["Покупець в активній угоді просить поспілкуватися з чинним клієнтом про досвід використання."],"workflow_steps":["Зберегти угоду, питання покупця, роль співрозмовника та доречність розмови на цій стадії.","Добрати клієнтів за досвідом і контекстом; врахувати попередні запити, незавершені участі й рекомендацію власника відносин.","Отримати згоду конкретного клієнта на учасників, тему й спосіб передачі контакту; загальний дозвіл на логотип або кейс не підміняє цю згоду.","Після дозволу координувати знайомство й час; при відмові обрати інший придатний варіант без розкриття контакту.","Зберегти факт участі, короткий дозволений висновок і наступну дію в угоді; заплановану зустріч не записувати як проведену або гарантований виграш."],"requirements":["Є запит покупця, власники угоди та відносин із клієнтом.","Є дозволений перелік кандидатів, історія участі й правила передачі контактів."],"limitations":["Це не реферальна винагорода, права на публікацію кейсу або лише підбір часу зустрічі.","Джерело є рекомендацією постачальника customer reference management, а не незалежним кейсом результативності.","Участь клієнта не гарантує виграшу; запис або публікація розмови потребують окремого дозволу.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Продавець передає контакт клієнта покупцю без згоди. Досвід клієнта не відповідає запиту, а кілька менеджерів одночасно просять його про нові розмови."],"synonyms":["референсний клієнт для угоди","customer reference call","клієнта перевантажують розмовами з покупцями"],"search_queries":["як погодити розмову покупця з чинним клієнтом без передачі контакту без згоди"],"sources":[{"type":"vendor_documentation","url":"https://www.point-of-reference.com/resources-center/how-and-why-to-train-sales-teams-on-customer-references","title":"Point of Reference: Sales teams and customer references","checked_at":"2026-10-10","supports":"Рекомендація постачальника: доречна стадія угоди, відповідність досвіду, консультація власника відносин, погоджений контакт, координація та облік результату й використання. Наші правила згоди, навантаження й маршрут винятків — проєктна модель; ефективність не доведена клієнтським кейсом."},{"type":"inferred_pattern","title":"Редакційна модель комерційних запитів і рекламних меж","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують власні продукти або рекомендації; готову реалізацію PlanFix чи клієнтський результат CRMCUSTOMS не підтверджено."}],"status":"draft","variants":[{"id":"customer-reference-call-consent-match-tracked","title":"Контроль із підтвердженням результату","description":"Для покупця добирають клієнта з доречним досвідом, погоджують конкретну участь і зберігають факт розмови, щоб не перевантажувати одних клієнтів запитами.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Покупець попросив досвід компанії зі схожим процесом. Власник відносин погодив кандидата, клієнт дозволив конкретну розмову; після участі менеджер записав результат і не включив його до наступного запиту автоматично.","implementation_methods":["Вести запити на референсну участь із придатністю, згодою та історією використання.","Пов’язувати фактичну участь із угодою та наступною дією без автоматичного виграшу."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Є запит покупця, власники угоди та відносин із клієнтом.","Є дозволений перелік кандидатів, історія участі й правила передачі контактів."],"limitations":["Це не реферальна винагорода, права на публікацію кейсу або лише підбір часу зустрічі.","Джерело є рекомендацією постачальника customer reference management, а не незалежним кейсом результативності.","Участь клієнта не гарантує виграшу; запис або публікація розмови потребують окремого дозволу."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0255","reason":"Право використати матеріал не є згодою людини на конкретну розмову."},{"type":"related","target_id":"AUT-0561","reason":"Реферальна винагорода прив’язана до покупки; участь клієнта не запускає її автоматично."},{"type":"related","target_id":"AUT-0567","reason":"Узгодження часу працює після добору й дозволу; вільний календар не підтверджує придатності або згоди."}],"configurator_questions":[{"id":"customer-reference-call-consent-match-matching","question":"Чи кандидатів добирають із кількох команд або реєстрів?","help_text":"Погодьте відповідність досвіду, власників відносин та доступну історію навантаження.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Погодьте відповідність досвіду, власників відносин та доступну історію навантаження."}]},{"id":"customer-reference-call-consent-match-consent","question":"Чи потрібні окремі умови участі для різних тем або груп покупців?","help_text":"Зберігайте точне охоплення згоди; минула участь не дозволяє нове використання.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Зберігайте точне охоплення згоди; минула участь не дозволяє нове використання."}]}]},{"schema_version":1,"id":"AUT-0591","slug":"technical-referral-attribution-exclusion-review","title":"Перевірка технічних переходів перед виключенням джерела трафіку","summary":"Повернення з платіжного або службового домену відокремлюють від справжнього залучення; виключення не приховує всі події чи цінні зовнішні джерела.","problem":"Платіжний сервіс отримав кредит за залучення покупця. Команда приховала всі referrers або очікує, що нове виключення негайно перепише попередню історію.","outcome":"Погоджені технічні переходи мають перевірені правила виключення з атрибуції; справжні джерела й події збережені, а історичні обмеження пояснені.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","owner"],"industries":["cross-industry"],"triggers":["У звіті залучення з’явився сторонній домен, через який клієнт виконує службову дію й повертається на сайт."],"workflow_steps":["Зберегти потік аналітики, домен, маршрут повернення та приклади подій; не називати будь-який зовнішній referrer технічним.","Перевірити роль домену: службова дія чи фактичне залучення; власні домени й розрив ідентифікації передати на окрему перевірку.","Погодити точні умови виключення та контрольні справжні джерела; широке правило не застосовувати до всіх переходів.","Прочитати збережені умови й перевірити дозволений контрольний маршрут та події; виключення джерела не означає видалення події.","Після потрібної затримки зіставити нові спостереження й історичну атрибуцію; старий кредит джерела не вважати автоматично переписаним."],"requirements":["Є доступ до потоку аналітики, умов виключення та контрольних маршрутів.","Маркетолог погоджує технічні домени й перелік справжніх джерел, які потрібно зберегти."],"limitations":["Виключення referrer не з’єднує ідентифікатори між доменами й не фільтрує всі події.","Старі джерела можуть лишатися через попередню атрибуцію; зміна не гарантує негайного переписування історії.","Механізм ignore_referrer і його значення перевіряють за фактичним контрактом; параметр не встановлюють на всіх сторінках.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Платіжний сервіс отримав кредит за залучення покупця. Команда приховала всі referrers або очікує, що нове виключення негайно перепише попередню історію."],"synonyms":["технічний referral після оплати","unwanted referrals перевірка","платіжний домен отримує кредит залучення"],"search_queries":["як прибрати платіжний сервіс із джерел залучення без втрати справжніх переходів"],"sources":[{"type":"vendor_documentation","url":"https://support.google.com/analytics/answer/10327750?hl=en","title":"Google Analytics: Identify unwanted referrals","checked_at":"2026-10-10","supports":"Описано службові домени, ignore_referrer, умови OR та збереження попереднього джерела в наступній атрибуції. Це виключення джерела, не всіх подій. Загальне застосування параметра може втратити дані; навіть false не трактують як безпечне вимкнення."},{"type":"inferred_pattern","title":"Редакційна модель маркетингових рішень і партнерської готовності","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують власні продукти; готову реалізацію PlanFix чи клієнтський результат CRMCUSTOMS не підтверджено."}],"status":"draft","variants":[{"id":"technical-referral-attribution-exclusion-review-tracked","title":"Контроль із підтвердженням результату","description":"Повернення з платіжного або службового домену відокремлюють від справжнього залучення; виключення не приховує всі події чи цінні зовнішні джерела.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"У звіті покупки віднесли до платіжного домену. Маркетолог перевірив маршрут, погодив вузьке виключення й звірив новий контрольний перехід; старі покупки позначив як історичне обмеження.","implementation_methods":["Вести погоджені технічні домени та точні умови виключення.","Звіряти контрольні службові й справжні переходи без видалення подій."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Є доступ до потоку аналітики, умов виключення та контрольних маршрутів.","Маркетолог погоджує технічні домени й перелік справжніх джерел, які потрібно зберегти."],"limitations":["Виключення referrer не з’єднує ідентифікатори між доменами й не фільтрує всі події.","Старі джерела можуть лишатися через попередню атрибуцію; зміна не гарантує негайного переписування історії.","Механізм ignore_referrer і його значення перевіряють за фактичним контрактом; параметр не встановлюють на всіх сторінках."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0532","reason":"Збереження ідентифікації між власними доменами не підміняється приховуванням стороннього джерела."},{"type":"related","target_id":"AUT-0104","reason":"Ключ переходу до бота зберігає контекст звернення, а не змінює attribution referrer."},{"type":"related","target_id":"AUT-0525","reason":"Вибір моделі внеску каналів не визначає, який технічний домен слід виключити."}],"configurator_questions":[{"id":"technical-referral-attribution-exclusion-review-routes","question":"Чи клієнт повертається через кілька службових сервісів?","help_text":"Погодьте роль кожного домену та окремі контрольні маршрути.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Погодьте роль кожного домену та окремі контрольні маршрути."}]},{"id":"technical-referral-attribution-exclusion-review-history","question":"Чи потрібно порівняти новий звіт із попередніми періодами?","help_text":"Позначте час зміни й межі історичної атрибуції без обіцянки ретроспективного виправлення.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Позначте час зміни й межі історичної атрибуції без обіцянки ретроспективного виправлення."}]}]},{"schema_version":1,"id":"AUT-0592","slug":"internal-search-unmet-content-demand-review","title":"Доповнення контенту за незадоволеними внутрішніми пошуками","summary":"Повторні запити на сайті зіставляють із фактичними результатами; підтверджена прогалина отримує рішення про матеріал, а не лише звіт частоти.","problem":"Відвідувачі шукають відповідь усередині сайту, але потрібного матеріалу немає. Команда бачить популярні слова й створює нові сторінки без перевірки наявного контенту або помилки пошукового механізму.","outcome":"Підтверджена прогалина внутрішнього пошуку має погоджене доповнення чи інше рішення; після зміни контрольний запит знаходить доречний матеріал.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","owner"],"industries":["cross-industry"],"triggers":["Повторюваний внутрішній запит має сигнал відсутнього результату або потребує перевірки доречності відповіді."],"workflow_steps":["Отримати дозволені пошукові запити за період із потрібними подіями; відкинути персональні дані й не змішувати з зовнішніми SEO-запитами.","Зіставити частоту з результатом пошуку або виконати контрольний запит; сама популярність не доводить прогалини.","Знайти наявний доречний матеріал і причину проблеми: відсутній зміст, назва, навігація або пошуковий механізм.","Редактор погоджує доповнення матеріалу, нову відповідь чи виправлення пошуку з власником; повтори теми об’єднати до створення контенту.","Після дозволеної публікації виконати контрольні запити й звірити доречність відповіді; зміна кількості пошуків не є самостійним доказом задоволення потреби."],"requirements":["Є дозволені search_term та контроль фактичного результату пошуку.","Є власник контенту, правила розгляду запитів та перевірка після публікації."],"limitations":["Подія перегляду пошуку не підтверджує нульового результату; цей сигнал потребує окремого джерела або ручної перевірки.","Автоматичне вимірювання за URL може не охопити всі форми пошуку; охоплення перевіряють.","Запити з персональними даними не передають до загального маркетингового звіту.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Відвідувачі шукають відповідь усередині сайту, але потрібного матеріалу немає. Команда бачить популярні слова й створює нові сторінки без перевірки наявного контенту або помилки пошукового механізму."],"synonyms":["прогалини контенту за site search","пошук сайту не дає потрібної відповіді","внутрішні запити для контент плану"],"search_queries":["як доповнювати контент за внутрішніми пошуковими запитами на які сайт не дає відповіді"],"sources":[{"type":"vendor_documentation","url":"https://support.google.com/analytics/answer/12664847?hl=en","title":"Google Analytics: Explore playbook — site search","checked_at":"2026-10-10","supports":"Цільовий розділ показує аналіз внутрішніх search_term з фільтром view_search_results. Не переносимо застарілі твердження про доступність інших звітів. Частота не доводить прогалини; редакційне рішення й перевірка відповіді — проєктна модель."},{"type":"vendor_documentation","url":"https://support.google.com/analytics/answer/9216061?hl=en","title":"Google Analytics: Enhanced measurement events","checked_at":"2026-10-10","supports":"Прочитано site search: подію запускає пошуковий URL-параметр, search_term заповнює Search term. Описано вимогу не збирати персональні дані. Подія не повідомляє кількості знайдених результатів."},{"type":"inferred_pattern","title":"Редакційна модель маркетингових рішень і партнерської готовності","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують власні продукти; готову реалізацію PlanFix чи клієнтський результат CRMCUSTOMS не підтверджено."}],"status":"draft","variants":[{"id":"internal-search-unmet-content-demand-review-tracked","title":"Контроль із підтвердженням результату","description":"Повторні запити на сайті зіставляють із фактичними результатами; підтверджена прогалина отримує рішення про матеріал, а не лише звіт частоти.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Відвідувачі повторно шукають умови підключення. Редактор перевірив запит, знайшов неповну відповідь і доповнив наявну сторінку; після публікації підтвердив, що пошук показує її.","implementation_methods":["Об’єднувати повторні теми й перевіряти фактичну прогалину до завдання редактору.","Пов’язувати рішення про матеріал із контрольними пошуковими запитами."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Є дозволені search_term та контроль фактичного результату пошуку.","Є власник контенту, правила розгляду запитів та перевірка після публікації."],"limitations":["Подія перегляду пошуку не підтверджує нульового результату; цей сигнал потребує окремого джерела або ручної перевірки.","Автоматичне вимірювання за URL може не охопити всі форми пошуку; охоплення перевіряють.","Запити з персональними даними не передають до загального маркетингового звіту."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0396","reason":"Підняття товару в результатах не створює відсутню змістовну відповідь."},{"type":"related","target_id":"AUT-0103","reason":"Контент-план керує публікацією після рішення, а не підтверджує незадоволений пошуковий запит."},{"type":"related","target_id":"AUT-0565","reason":"Зовнішній сезонний попит відрізняється від потреб відвідувача всередині сайту."}],"configurator_questions":[{"id":"internal-search-unmet-content-demand-review-signals","question":"Чи потрібен окремий сигнал кількості результатів або невдалої відповіді?","help_text":"Погодьте вимірювання без персональних даних і перевірте охоплення форми.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Погодьте вимірювання без персональних даних і перевірте охоплення форми."}]},{"id":"internal-search-unmet-content-demand-review-sites","question":"Чи аналіз охоплює кілька мовних версій або сайтів?","help_text":"Зберігайте контекст та відповідні матеріали; однакова фраза не означає однакової прогалини.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Зберігайте контекст та відповідні матеріали; однакова фраза не означає однакової прогалини."}]}]},{"schema_version":1,"id":"AUT-0593","slug":"dynamic-ad-copy-combination-approval","title":"Погодження сумісних текстів для автоматичного складання реклами","summary":"Заголовки й описи перевіряють як можливі поєднання; обов’язкова умова пропозиції не губиться при перестановці або скороченні тексту.","problem":"Окремо погоджені заголовки утворили суперечливу обіцянку. Важливу умову закріпили в необов’язковій позиції, а один preview помилково вважають перевіркою всіх показів.","outcome":"Набір рекламних текстів має погоджені сумісні твердження та перевірені правила збереження потрібних умов; невідомі формати показу залишаються явними.","category":"marketing","subcategory":"campaign-operations","roles":["marketer","owner"],"industries":["cross-industry"],"triggers":["Готують або змінюють набір текстів, які рекламна платформа автоматично комбінує."],"workflow_steps":["Зберегти редакцію пропозиції, заголовки, описи, істотні умови та дозволене твердження кожного фрагмента.","Перевірити можливі поєднання й перестановки: суперечності, різні строки, несумісні ціни та втрату контексту; окремий текст не схвалює весь набір.","Уповноважений власник погоджує обов’язкові умови й допустиме закріплення; кілька альтернатив одного місця перевірити кожну.","Прочитати фактичний набір і позиції, врахувати скорочення, необов’язкові поля та додаткові активи; preview не оголошувати вичерпним.","Перед використанням погодити перевірену редакцію й відкриті обмеження; після зміни фрагмента повторити зачеплені поєднання без автоматичного схвалення платформи як доказу змісту."],"requirements":["Є погоджена пропозиція, набір фрагментів і власник змістового рішення.","Є доступ до фактичних активів, закріплення та правил потрібного рекламного формату."],"limitations":["Це не юридичний висновок; обов’язкові умови визначає уповноважений фахівець.","Google responsive search ads має власні позиції та додаткові способи використання активів; гарантії не переносять на інші формати.","Preview не показує всіх комбінацій; схвалення платформи не доводить відсутності суперечливої обіцянки.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Окремо погоджені заголовки утворили суперечливу обіцянку. Важливу умову закріпили в необов’язковій позиції, а один preview помилково вважають перевіркою всіх показів."],"synonyms":["сумісність заголовків і описів реклами","обов’язкова умова в responsive ads","суперечливі комбінації рекламного тексту"],"search_queries":["як перевірити поєднання рекламних заголовків щоб автоматична реклама не губила умови пропозиції"],"sources":[{"type":"vendor_documentation","url":"https://support.google.com/google-ads/answer/7684791?hl=en","title":"Google Ads: About responsive search ads","checked_at":"2026-10-10","supports":"Описано комбінування й порядок, неповний preview, закріплення та необов’язкові позиції. Альтернативи однієї позиції чергуються; є додаткове використання активів. Джерело не підтверджує ефективності або універсальної правової відповідності нашого контролю."},{"type":"inferred_pattern","title":"Редакційна модель маркетингових рішень і партнерської готовності","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують власні продукти; готову реалізацію PlanFix чи клієнтський результат CRMCUSTOMS не підтверджено."}],"status":"draft","variants":[{"id":"dynamic-ad-copy-combination-approval-tracked","title":"Контроль із підтвердженням результату","description":"Заголовки й описи перевіряють як можливі поєднання; обов’язкова умова пропозиції не губиться при перестановці або скороченні тексту.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"У наборі були різні строки акції, а уточнення стояло в необов’язковому описі. Маркетолог прибрав суперечність і погодив місце істотної умови до запуску; один preview не закрив усі формати.","implementation_methods":["Вести редакцію набору та перевірки сумісності тверджень.","Звіряти збережені фрагменти й правила показу потрібних умов перед запуском."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Є погоджена пропозиція, набір фрагментів і власник змістового рішення.","Є доступ до фактичних активів, закріплення та правил потрібного рекламного формату."],"limitations":["Це не юридичний висновок; обов’язкові умови визначає уповноважений фахівець.","Google responsive search ads має власні позиції та додаткові способи використання активів; гарантії не переносять на інші формати.","Preview не показує всіх комбінацій; схвалення платформи не доводить відсутності суперечливої обіцянки."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0540","reason":"Персональні поля й адресат відрізняються від сумісності кількох незалежних рекламних фрагментів."},{"type":"related","target_id":"AUT-0337","reason":"Маркування співпраці є конкретним disclosure публікації; тут перевіряють твердження й умови в автоматичних поєднаннях."},{"type":"related","target_id":"AUT-0106","reason":"Виправлення відхилення платформи не підтверджує змістової узгодженості схваленого набору."}],"configurator_questions":[{"id":"dynamic-ad-copy-combination-approval-offers","question":"Чи набір містить кілька пропозицій із різними умовами?","help_text":"Погодьте дозволені поєднання або розділення наборів без змішування обіцянок.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Погодьте дозволені поєднання або розділення наборів без змішування обіцянок."}]},{"id":"dynamic-ad-copy-combination-approval-formats","question":"Чи активи можуть використовуватися в кількох форматах або спільних місцях?","help_text":"Перевірте область використання, позиції та невідомі випадки показу.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Перевірте область використання, позиції та невідомі випадки показу."}]}]},{"schema_version":1,"id":"AUT-0594","slug":"partner-designation-renewal-eligibility-control","title":"Контроль готовності до продовження партнерського статусу","summary":"Компанія звіряє докази кваліфікації та вікно продовження партнерської програми; поточний бал не підміняє зовнішній стан участі.","problem":"Команда перевіряє лише загальний бал і пропускає потрібну метрику або строк продовження. Внутрішня таблиця показує готовність, але зовнішній сервіс ще не врахував сертифікації чи клієнтів.","outcome":"Партнерський напрям має підтверджену придатність до продовження, пояснені прогалини й актуальний зовнішній статус; кваліфікація та чинна участь не змішані.","category":"sales-crm","subcategory":"sales-operations","roles":["sales-manager","owner"],"industries":["cross-industry"],"triggers":["Наближається вікно продовження партнерського статусу або змінився доказ кваліфікації."],"workflow_steps":["Зберегти програму, напрям, редакцію умов, чинний статус, дату завершення й фактичне вікно продовження.","Зібрати розшифровані зовнішні метрики та історію кваліфікації; загальний бал не підміняє обов’язкові складові.","Звірити охоплення клієнтів, прив’язки підтверджень і час оновлення; неврахований доказ передати відповідальному, не оголошувати автоматично втраченим.","Погодити дії для прогалин і потрібне рішення в межах строку; Qualified не називати Enrolled, а денне падіння балу — припиненням чинної участі.","Перед продовженням перечитати зовнішню придатність та після дозволеної дії звірити новий період і статус; фінансову оплату вести окремим процесом."],"requirements":["Є партнерська програма з перевіреними правилами й власник напряму.","Є доступ до зовнішнього статусу, метрик, строків та історії кваліфікації."],"limitations":["Це не реєстрація угоди, приймання co-sell referral або перевірка кваліфікації окремого працівника.","Числові пороги, строки й затримки Microsoft не є правилами PlanFix чи всіх партнерських програм.","Внутрішній розрахунок не гарантує зовнішнього схвалення; оплата й активація переваг мають окремі підтвердження.","Права й можливості цільового середовища перевіряють на аудиті; години попередні."],"problems":["Команда перевіряє лише загальний бал і пропускає потрібну метрику або строк продовження. Внутрішня таблиця показує готовність, але зовнішній сервіс ще не врахував сертифікації чи клієнтів."],"synonyms":["partner designation renewal eligibility","прогалини партнерської кваліфікації","Qualified не означає Enrolled"],"search_queries":["як не пропустити продовження партнерського статусу і перевірити зовнішню кваліфікацію"],"sources":[{"type":"vendor_documentation","url":"https://learn.microsoft.com/en-us/partner-center/membership/partner-capability-score","title":"Microsoft Partner Center: Partner Capability Score","checked_at":"2026-10-10","supports":"Описано метрики, історію вікна кваліфікації, Qualified/Enrolled, renewal eligibility та затримки даних. Чинна участь відрізняється від денного score. Не переносимо конкретні пороги, періоди або правила Microsoft на інші програми."},{"type":"inferred_pattern","title":"Редакційна модель маркетингових рішень і партнерської готовності","supports":"Погодження, винятки, приклади, питання й години — гіпотези для аудиту. Джерела описують власні продукти; готову реалізацію PlanFix чи клієнтський результат CRMCUSTOMS не підтверджено."}],"status":"draft","variants":[{"id":"partner-designation-renewal-eligibility-control-tracked","title":"Контроль із підтвердженням результату","description":"Компанія звіряє докази кваліфікації та вікно продовження партнерської програми; поточний бал не підміняє зовнішній стан участі.","best_for":["Команда має погоджені правила та перевірені джерела даних."],"example":"Напрям наближався до продовження. Власник знайшов невраховане підтвердження, перевірив час оновлення й історичну придатність; після дозволеного продовження прочитав зовнішній статус нового періоду.","implementation_methods":["Вести календар програми з доказами метрик і зовнішнім станом кваліфікації.","Контролювати прогалини та підтверджений результат продовження без автоматичного визнання внутрішнього балу."],"complexity":"medium","hours_min":22,"hours_max":44,"requirements":["Є партнерська програма з перевіреними правилами й власник напряму.","Є доступ до зовнішнього статусу, метрик, строків та історії кваліфікації."],"limitations":["Це не реєстрація угоди, приймання co-sell referral або перевірка кваліфікації окремого працівника.","Числові пороги, строки й затримки Microsoft не є правилами PlanFix чи всіх партнерських програм.","Внутрішній розрахунок не гарантує зовнішнього схвалення; оплата й активація переваг мають окремі підтвердження."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0238","reason":"Реєстрація конкретної угоди не підтверджує продовження статусу компанії."},{"type":"related","target_id":"AUT-0576","reason":"Прийняття запрошення до спільного продажу має інший об’єкт і строк."},{"type":"related","target_id":"AUT-0124","reason":"Кваліфікація працівника для роботи є лише можливим доказом, а не повним результатом партнерської програми."}],"configurator_questions":[{"id":"partner-designation-renewal-eligibility-control-programs","question":"Чи компанія підтримує кілька напрямів або партнерських програм?","help_text":"Зберігайте окремі правила, періоди та статуси без універсальних порогів.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Зберігайте окремі правила, періоди та статуси без універсальних порогів."}]},{"id":"partner-designation-renewal-eligibility-control-evidence","question":"Чи метрики потрібно зіставляти з кількома внутрішніми джерелами доказів?","help_text":"Перевірте прив’язки, затримку й допустимий доступ; внутрішні дані не замінюють зовнішній результат.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Перевірте прив’язки, затримку й допустимий доступ; внутрішні дані не замінюють зовнішній результат."}]}]}];
